import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"功能概览","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features.md","filePath":"features.md"}'),l={name:"features.md"};function n(i,t,s,d,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="功能概览" tabindex="-1">功能概览 <a class="header-anchor" href="#功能概览" aria-label="Permalink to &quot;功能概览&quot;">​</a></h1><p>EmuTrain 由四个主要模块构成，通过底部导航栏切换：<strong>旅行</strong>、<strong>搜索</strong>、<strong>其他</strong>、<strong>设置</strong>。</p><hr><h2 id="🚄-旅行-主页" tabindex="-1">🚄 旅行（主页） <a class="header-anchor" href="#🚄-旅行-主页" aria-label="Permalink to &quot;🚄 旅行（主页）&quot;">​</a></h2><p>旅行页面是 EmuTrain 的核心主页，用于管理和查看您的行程记录。</p><h3 id="行程卡片" tabindex="-1">行程卡片 <a class="header-anchor" href="#行程卡片" aria-label="Permalink to &quot;行程卡片&quot;">​</a></h3><p>有车时，主页会以卡片形式展示每段行程，包含：</p><ul><li><strong>车次信息</strong>（如 G1 次）</li><li><strong>上下车站</strong>及<strong>时间日期</strong></li><li><strong>站点信息</strong>（始发 → 终到）</li></ul><p>点击卡片可进入详细信息页，查看：</p><ul><li>列车运行<strong>状态</strong></li><li><strong>坐席</strong>类型（一等座 / 二等座 / 商务座等）</li><li><strong>乘车日期</strong></li><li><strong>始发终到</strong>与具体<strong>站点区间</strong></li><li>点击右侧按钮可打开<strong>线路走向图</strong></li></ul><h3 id="添加行程" tabindex="-1">添加行程 <a class="header-anchor" href="#添加行程" aria-label="Permalink to &quot;添加行程&quot;">​</a></h3><p>暂无行程时，点击右下角的 <strong>+</strong> 按钮即可添加新行程，支持：</p><ul><li>按<strong>车次</strong>查询并选择区间</li><li>按<strong>车站</strong>查询</li><li>填写<strong>坐席</strong>信息保存记录</li></ul><h3 id="行程管理" tabindex="-1">行程管理 <a class="header-anchor" href="#行程管理" aria-label="Permalink to &quot;行程管理&quot;">​</a></h3><ul><li>按<strong>出发时间</strong>排序</li><li>支持<strong>清空所有</strong>行程（需二次确认）</li></ul><hr><h2 id="🔍-搜索" tabindex="-1">🔍 搜索 <a class="header-anchor" href="#🔍-搜索" aria-label="Permalink to &quot;🔍 搜索&quot;">​</a></h2><p>搜索是 EmuTrain 最强大的核心功能之一，支持两种查询方式。</p><h3 id="车次查询" tabindex="-1">车次查询 <a class="header-anchor" href="#车次查询" aria-label="Permalink to &quot;车次查询&quot;">​</a></h3><p>输入车次号（如 <code>G1</code>、<code>D301</code>、<code>K27</code>）后，可查询该次列车的：</p><ul><li><strong>完整停靠站点</strong>与到发时刻</li><li><strong>担当动车组</strong>型号与车组号</li><li><strong>重联编组</strong>信息</li><li>始发终到站及运行时间</li></ul><p><strong>支持的数据源：</strong></p><table tabindex="0"><thead><tr><th>数据源</th><th>特点</th></tr></thead><tbody><tr><td>Rail.re</td><td>第三方 API，数据更丰富，含重联与城际信息</td></tr><tr><td>RailGo</td><td>第三方 API，数据更丰富，含重联与城际信息</td></tr><tr><td>12306 官方</td><td>官方权威，最准确，但不显示重联与城际等信息</td></tr></tbody></table><h3 id="动车组查询-车号-交路查询" tabindex="-1">动车组查询（车号/交路查询） <a class="header-anchor" href="#动车组查询-车号-交路查询" aria-label="Permalink to &quot;动车组查询（车号/交路查询）&quot;">​</a></h3><p>输入动车组车组号（如 <code>CRH380A-1001</code>、<code>CR400BF-4501</code>）后，可查询：</p><ul><li><strong>当日担当交路</strong>（运行的具体车次）</li><li><strong>配属路局</strong>与<strong>配属段</strong></li><li><strong>制造厂家</strong></li><li><strong>相关站点信息</strong></li></ul><p><strong>支持的数据源：</strong></p><table tabindex="0"><thead><tr><th>数据源</th><th>特点</th></tr></thead><tbody><tr><td>Rail.re</td><td>综合车型信息</td></tr><tr><td>RailGo</td><td>综合车型信息</td></tr><tr><td>MoeFactory</td><td>全面的车型数据库</td></tr></tbody></table><hr><h2 id="🛠️-其他-工具箱" tabindex="-1">🛠️ 其他（工具箱） <a class="header-anchor" href="#🛠️-其他-工具箱" aria-label="Permalink to &quot;🛠️ 其他（工具箱）&quot;">​</a></h2><p>工具箱汇集了多项实用功能：</p><h3 id="车站大屏" tabindex="-1">车站大屏 <a class="header-anchor" href="#车站大屏" aria-label="Permalink to &quot;车站大屏&quot;">​</a></h3><p>选择车站，即可查看该车站目前的<strong>实时出发/到达大屏</strong>信息（仅供参考）。<br> 数据来源：<a href="https://rail.moefactory.com" target="_blank" rel="noreferrer">MoeFactory</a></p><h3 id="线路制造处" tabindex="-1">线路制造处 <a class="header-anchor" href="#线路制造处" aria-label="Permalink to &quot;线路制造处&quot;">​</a></h3><p>自建与管理线路图：</p><ul><li><strong>新建线路</strong>：自定义站点、线路名称</li><li><strong>编辑线路</strong>：修改已有站点与顺序</li><li><strong>导入 JSON</strong>：从文件导入线路数据</li><li><strong>线路商店</strong>：浏览与下载社区共享线路</li></ul><h3 id="速度计" tabindex="-1">速度计 <a class="header-anchor" href="#速度计" aria-label="Permalink to &quot;速度计&quot;">​</a></h3><p>利用 GPS 实时测量当前列车的行驶速度。</p><blockquote><p>⚠️ 实验性功能，数据可能不准，仅供娱乐参考。</p></blockquote><h3 id="动车图鉴" tabindex="-1">动车图鉴 <a class="header-anchor" href="#动车图鉴" aria-label="Permalink to &quot;动车图鉴&quot;">​</a></h3><p>精选了一批特殊列车（特殊涂装、节日彩绘、稀有型号等）供爱好者欣赏。<br> 数据来源：<a href="https://china-emu.cn/Trains/ALL/" target="_blank" rel="noreferrer">china-emu.cn</a></p><h3 id="关于软件" tabindex="-1">关于软件 <a class="header-anchor" href="#关于软件" aria-label="Permalink to &quot;关于软件&quot;">​</a></h3><p>展示软件版本、数据来源与鸣谢名单，也可在此查看最新版本更新。</p><h3 id="友情链接" tabindex="-1">友情链接 <a class="header-anchor" href="#友情链接" aria-label="Permalink to &quot;友情链接&quot;">​</a></h3><p>推荐的相关 APP 与网站：</p><ul><li><strong>路路通</strong> — 国铁综合出行 APP</li><li><strong>动车组查询（Rail.re）</strong> — 动车组交路查询网站</li><li><strong>RailGo</strong> — 铁路信息查询 APP</li><li><strong>MoeFactory 车箱</strong> — 综合铁路数据平台</li><li><strong>动车组图鉴（china-emu.cn）</strong> — 动车组图片数据库</li></ul><hr><h2 id="⚙️-设置" tabindex="-1">⚙️ 设置 <a class="header-anchor" href="#⚙️-设置" aria-label="Permalink to &quot;⚙️ 设置&quot;">​</a></h2><h3 id="主题设置" tabindex="-1">主题设置 <a class="header-anchor" href="#主题设置" aria-label="Permalink to &quot;主题设置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>深色模式</td><td>手动切换深色 / 浅色主题</td></tr><tr><td>子夜模式</td><td>深度黑色背景，护眼夜间模式</td></tr><tr><td>跟随系统</td><td>随系统深浅色自动切换</td></tr><tr><td>主题色</td><td>自定义颜色种子，支持 Material You 莫奈壁纸色</td></tr></tbody></table><h3 id="图标显示" tabindex="-1">图标显示 <a class="header-anchor" href="#图标显示" aria-label="Permalink to &quot;图标显示&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>显示列车图标</td><td>开关搜索结果中的动车组车型图标</td></tr><tr><td>显示路局图标</td><td>开关路局图标展示</td></tr></tbody></table><h3 id="数据源" tabindex="-1">数据源 <a class="header-anchor" href="#数据源" aria-label="Permalink to &quot;数据源&quot;">​</a></h3><p>可分别为<strong>车次查询</strong>、<strong>车号/交路查询</strong>、<strong>车站查询</strong>单独指定数据源。</p><h3 id="自动更新" tabindex="-1">自动更新 <a class="header-anchor" href="#自动更新" aria-label="Permalink to &quot;自动更新&quot;">​</a></h3><ul><li><strong>自动检测更新</strong>：启动时自动检测新版本并弹窗提示</li><li><strong>静默更新数据库</strong>：后台自动更新本地站名、列车等数据文件</li></ul><h3 id="应用信息" tabindex="-1">应用信息 <a class="header-anchor" href="#应用信息" aria-label="Permalink to &quot;应用信息&quot;">​</a></h3><ul><li>点击<strong>版本号</strong>可手动检查更新</li><li>点击<strong>开发者</strong>可跳转至 <a href="https://github.com/CrYinLang" target="_blank" rel="noreferrer">GitHub</a> 与<a href="https://www.douyin.com/user/MS4wLjABAAAA-bZxFhm96BhUle209c1gQ5HskPw4y-olT2PwOYevJ6fSkkHmIV23EuGfjaq1xHCx" target="_blank" rel="noreferrer">抖音</a>主页</li></ul>',58)])])}const b=r(l,[["render",n]]);export{c as __pageData,b as default};
